/// <summary>
/// Class is used to get record from table <c>EcoResProductMasterModelingPolicy</c> based on pricingObject parameter.
/// </summary>
internal abstract class GUPPricingAttributeEcoResProductMasterModelingPolicy extends GUPAbstractPricingAttribute implements GUPIPricingAttribute
{
}

Method.Source:
    protected EcoResProductMasterModelingPolicy getTableRecord(Common _pricingObject)
    {
        SalesLine                           salesLine;
        SalesQuotationLine                  salesQoutationLine;
        EcoResProduct                       product;
        EcoResProductMasterModelingPolicy   modelingPolicy;

        Switch (_pricingObject.tableId)
        {

            case tableNum(SalesLine):
                salesLine = _pricingObject as SalesLine;
                if (salesLine)
                {
                    product = salesLine.inventTable().Product();
                }
                break;

            case tableNum(SalesQuotationLine):
                salesQoutationLine = _pricingObject as SalesQuotationLine;
                if (salesQoutationLine)
                {
                    product = salesQoutationLine.inventTable().Product();
                }
                break;
        }

        if (product)
        {
            modelingPolicy = EcoResProductMasterModelingPolicy::findByProductMaster(product.RecId);
        }

        return modelingPolicy;
    }

    protected QueryBuildDataSource getQueryBuildDatasource(Query _query, Map _qbdsMap = null)
    {
        QueryBuildDataSource qbdsRoot;

        if (_qbdsMap && _qbdsMap.exists(tableStr(EcoResProductMasterModelingPolicy)))
        {
            qbdsRoot = _qbdsMap.lookup(tableStr(EcoResProductMasterModelingPolicy));
        }
        else
        {
            qbdsRoot = _query.addDataSource(tableNum(EcoResProductMasterModelingPolicy));

            if (_qbdsMap)
            {
                _qbdsMap.insert(tableStr(EcoResProductMasterModelingPolicy), qbdsRoot);
            }
        }

        return qbdsRoot;
    }

    public Query buildPricingObjectQuery(Query _query, anytype _value, Map _qdbsMap = null)
    {
        QueryBuildDataSource qbds;

        qbds = this.getQueryBuildDatasource(_query, _qdbsMap);
        this.setQueryBuildDatasourceRange(qbds, _value);

        return _query;
    }
